import{_ as p,a0 as r,w as o,s as d,I as n,x as s,a1 as e,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"用 Ansible 來交付 Vagrant  實例 | LCTT x X-CMD","titleTemplate":false,"description":"用 Ansible 來交付 Vagrant  實例 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Ansible 來交付 Vagrant  實例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Ansible 來交付 Vagrant  實例 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160915 Using Ansible to Provision Vagrant Boxes","title":"用 Ansible 來交付 Vagrant  實例","tag":"201610","desc":""},"relativePath":"201610/20160915 Using Ansible to Provision Vagrant Boxes.md","filePath":"[post].md"}'),g={name:"201610/20160915 Using Ansible to Provision Vagrant Boxes.md"};function b(h,a,k,u,m,c){const i=r("Link");return o(),d("div",null,[a[25]||(a[25]=n("h1",{id:"用-ansible-來交付-vagrant-實例",tabindex:"-1"},[s("用 Ansible 來交付 Vagrant 實例 "),n("a",{class:"header-anchor",href:"#用-ansible-來交付-vagrant-實例","aria-label":"Permalink to “用 Ansible 來交付 Vagrant  實例”"},"​")],-1)),a[26]||(a[26]=n("p",null,[n("img",{src:"https://i1.wp.com/cdn.fedoramagazine.org/wp-content/uploads/2016/08/vagrant-plus-ansible.jpg?w=1352&ssl=1",alt:""})],-1)),n("p",null,[a[1]||(a[1]=s("Ansible 是一款系統管理員進行自動化運維的強大工具。Ansible 讓配置、交付、管理各種容器，軟件部署",-1)),e(i,{href:"https://ansible.com/"},{default:t(()=>[...a[0]||(a[0]=[s("變得非常簡單",-1)])]),_:1}),a[2]||(a[2]=s("。基於輕量級模組的架構非常適合系統管理，一個優點就是如果某個節點沒有被 Ansible 管理的話，它的資源就不會被使用。",-1))]),n("p",null,[a[4]||(a[4]=s("這篇文章介紹用 Ansible 來配置 ",-1)),e(i,{href:"https://www.vagrantup.com/"},{default:t(()=>[...a[3]||(a[3]=[s("Vagrant 實例",-1)])]),_:1}),a[5]||(a[5]=s("，它是一個配置好的基礎虛擬機映像，包含了開發環境中需要用到的工具。你可以用它來部署開發環境，然後和其他成員協同工作。用 Ansible，你可以用你的開發包自動化交付 Vagrant 實例。",-1))]),n("p",null,[a[7]||(a[7]=s("我們用 Fedora 24 做主機，用 ",-1)),e(i,{href:"https://centos.org/"},{default:t(()=>[...a[6]||(a[6]=[s("CentOS",-1)])]),_:1}),a[8]||(a[8]=s(" 7 來作 Vagrant 實例。",-1))]),a[27]||(a[27]=l(`<h3 id="設置工作環境" tabindex="-1">設置工作環境 <a class="header-anchor" href="#設置工作環境" aria-label="Permalink to “設置工作環境”">​</a></h3><p>在用 Ansible 配置 Vagrant 實例時，你需要做幾件準備的事情。首先在宿主機上安裝 Ansible 和 Vagrant，在你的主機上運行下面的命令來安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install ansible vagrant vagrant-libvirt</span></span></code></pre></div><p>上面的命令將 Ansible 和 Vagrant 在你的宿主機上，以及包括 Vagrant 的 libvirt 接口。Vagrant 並沒有提供託管你的虛擬機的功能，需要第三方工具比如：libirt、VirtualBox、VMWare 等等。這些工具可以直接與你的 Fedora 系統上的 libvirt 和 KVM 協同工作。</p><p>接着確認你的賬户在正確的 wheel 用户組當中，確保你可以運行系統管理員命令。如果你的賬號在安裝過程中就創建為管理員，那麼你就肯定在這個用户組裏。運行下面的命令查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>id | grep wheel</span></span></code></pre></div><p>如果你能看到輸出，那麼你的賬户就在這個組裏，可以進行下一步。如果沒有的話，你需要運行下面的命令，這一步需要你提供 root 賬户的密碼，將 &lt;username&gt; 換成你的用户名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>su -c &#39;usermod -a -G wheel &lt;username&gt;&#39;</span></span></code></pre></div><p>然後，你需要註銷然後重新登錄，確保在用户組裏。</p><p>現在要建立你的第一個 Vagrant 實例了，你需要用 Ansible 來配置它。</p><h3 id="設置-vagrant-實例" tabindex="-1">設置 Vagrant 實例 <a class="header-anchor" href="#設置-vagrant-實例" aria-label="Permalink to “設置 Vagrant 實例”">​</a></h3><p>配置一個鏡像實例之前，你需要先創建它。創建一個目錄，存放 Vagrant 實例 相關的文件，並且將它作為當前工作目錄，用下面這條命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p ~/lampbox &amp;&amp; cd ~/lampbox</span></span></code></pre></div><p>在創建鏡像實例之前，你需要搞清楚目的，這個鏡像實例是一個運行 CentOS 7 基礎系統，模板包括 Apache 的 Web 服務，MariaDB（MySQL 原開發者創建的一個流行的開源資料庫）資料庫和 PHP 服務。</p><p>初始化 Vagrant 實例，用 <code>vagrant init</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vagrant init centos/7</span></span></code></pre></div><p>這個命令初始化 Vagrant 實例，並創建一個名為 Vagrantfile 的文件，包含一些預先配置的變量。打開並編輯它，下面的命令顯示了用於這次配置的基本鏡像實例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>config.vm.box = &quot;centos/7&quot;</span></span></code></pre></div><p>現在設置端口轉發，以便你配置完畢 Vagrant 實例並讓它運行起來之後可以測試它。將下述配置加入到 Vagrantfile 的最終的 <code>end</code> 語句之前：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>config.vm.network &quot;forwarded_port&quot;, guest: 80, host: 8080</span></span></code></pre></div><p>這個命令將 Vagrant 實例 的 80 端口映射為主機的 8080 端口。</p><p>下一步是設置 Ansible 作為配置 Vagrant 實例的工具，將下述配置加入到 Vagrantfile 的 <code>end</code> 語句之前，將 Ansible 作為配置工具（provisioning provider）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>config.vm.provision :ansible do |ansible|</span></span>
<span class="line"><span>  ansible.playbook = &quot;lamp.yml&quot;</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>（必須將這三行在最後的 <code>end</code> 語句之前加入）注意 <code>ansible.playbook = &quot;lamp.yml&quot;</code> 這一句定義了配置鏡像實例的 Ansible playbook 的名字。</p><h3 id="創建-ansible-playbook" tabindex="-1">創建 Ansible playbook <a class="header-anchor" href="#創建-ansible-playbook" aria-label="Permalink to “創建 Ansible playbook”">​</a></h3><p>在 Ansible 之中，playbook 是指在你的遠端節點執行的策略，換句話説，它管理遠端節點的配置和部署。詳細的説，playbook 是一個 Yaml 文件，在裏面寫入你要在遠端節點上將要執行的任務。所以，你需要創建一個名為 lamp.yml 的 playbook 來配置鏡像實例。</p><p>在 Vagrantfile 相同的目錄裏創建一個 lamp.yml 文件，將下面的內容粘貼到文件當中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- hosts: all</span></span>
<span class="line"><span>  become: yes</span></span>
<span class="line"><span>  become_user: root</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>  - name: Install Apache</span></span>
<span class="line"><span>    yum: name=httpd state=latest</span></span>
<span class="line"><span>  - name: Install MariaDB</span></span>
<span class="line"><span>    yum: name=mariadb-server state=latest</span></span>
<span class="line"><span>  - name: Install PHP5</span></span>
<span class="line"><span>    yum: name=php state=latest</span></span>
<span class="line"><span>  - name: Start the Apache server</span></span>
<span class="line"><span>    service: name=httpd state=started</span></span>
<span class="line"><span>  - name: Install firewalld</span></span>
<span class="line"><span>    yum: name=firewalld state=latest</span></span>
<span class="line"><span>  - name: Start firewalld</span></span>
<span class="line"><span>    service: name=firewalld state=started</span></span>
<span class="line"><span>  - name: Open firewall</span></span>
<span class="line"><span>    command: firewall-cmd --add-service=http --permanent</span></span></code></pre></div><p>每一行代表的意思：</p><ul><li><code>hosts: all</code> 指定該 playbook 需要在 Ansible 配置文件中定義的所有主機上都執行，因為還沒定義主機， playbook 將只在本地運行。</li><li><code>sudo: true</code> 表明該任務需要用 root 權限運行。（LCTT 譯註：此語句上述配置中缺失。）</li><li><code>tasks:</code> 指定當 playbook 運行是需要執行的任務，在這一節之下： <ul><li><code>name: ...</code> 描述任務的名字</li><li><code>yum: ...</code> 描述該任務應該由 yum 模組執行，可選的 key=value 鍵值對將由 yum 模組所使用。</li></ul></li></ul><p>當 playbook 運行時，它會安裝最新的 Apache Web 服務（http），MariaDB 和 PHP。當安裝完畢並啓動防火牆 firewalld，給 Apache 打開一個端口。你可以通過編寫 playbook 來完成這些。現在可以配置它了。</p><h3 id="配置鏡像-實例" tabindex="-1">配置鏡像 實例 <a class="header-anchor" href="#配置鏡像-實例" aria-label="Permalink to “配置鏡像 實例”">​</a></h3><p>用 Ansible 配置 Vagrant 實例只需要以下幾步了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vagrant up --provider libvirt</span></span></code></pre></div><p>上面的命令運行 Vagrant 實例，將實例的基礎鏡像下載到宿主機當中（如果還沒下載的話），然後運行 lamp.yml 來進行配置。</p><p>如果一切正常，輸出應該和下面的例子類似：</p><p><img src="https://i1.wp.com/cdn.fedoramagazine.org/wp-content/uploads/2016/08/vagrant-ansible-playbook-run.png?w=574&amp;ssl=1" alt=""></p><p>這個輸出顯示鏡像實例已經被配置好了，現在檢查服務是否可用，在宿主機上打開瀏覽器，輸入 <code>http://localhost:8080</code>，記住本地主機的 8080 端口是 Vagrant 實例映射過來的 80 端口。你應該可以看到如下的 Apache 的歡迎界面。</p><p><img src="https://i0.wp.com/cdn.fedoramagazine.org/wp-content/uploads/2016/08/vagrant-ansible-apache-up.png?w=1004&amp;ssl=1" alt=""></p>`,39)),n("p",null,[a[10]||(a[10]=s("要修改你的 Vagrant 實例，你可以修改 lamp.yml，你能從 Ansible 的",-1)),e(i,{href:"http://docs.ansible.com/ansible/index.html"},{default:t(()=>[...a[9]||(a[9]=[s("官網",-1)])]),_:1}),a[11]||(a[11]=s("上找到很多文章。然後運行下面的命令來重新配置：",-1))]),a[28]||(a[28]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vagrant provision</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>現在我們知道怎麼用 Ansible 來配置 Vagrant 實例了。這只是一個基本的例子，但是你可以用這些工具來實現不同的例子。比如你可以用所需工具的最新版本來部署一個完整的應用。現在你可以用 Ansible 來配置你自己的遠端服務器和容器了。</p><hr>',4)),n("p",null,[a[13]||(a[13]=s("via: ",-1)),e(i,{href:"https://fedoramagazine.org/using-ansible-provision-vagrant-boxes/"},{default:t(()=>[...a[12]||(a[12]=[s("https://fedoramagazine.org/using-ansible-provision-vagrant-boxes/",-1)])]),_:1})]),n("p",null,[a[17]||(a[17]=s("作者：",-1)),e(i,{href:"http://h4xr.id.fedoraproject.org/"},{default:t(()=>[...a[14]||(a[14]=[s("Saurabh Badhwar",-1)])]),_:1}),a[18]||(a[18]=s(" 譯者：",-1)),e(i,{href:"https://github.com/jiajia9linuxer"},{default:t(()=>[...a[15]||(a[15]=[s("jiajia9linuxer",-1)])]),_:1}),a[19]||(a[19]=s(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...a[16]||(a[16]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[22]||(a[22]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[20]||(a[20]=[s("LCTT",-1)])]),_:1}),a[23]||(a[23]=s(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...a[21]||(a[21]=[s("Linux中國",-1)])]),_:1}),a[24]||(a[24]=s(" 榮譽推出",-1))])])}const V=p(g,[["render",b]]);export{v as __pageData,V as default};
